cat > src/boxOffice.test.ts <<'EOF'
import { describe, expect, test } from "bun:test";
import { BoxOfficeError, createBoxOffice, type BoxOffice } from "./boxOffice";

describe("BoxOfficeError", () => {
  test("carries a machine-readable code", () => {
    const error = new BoxOfficeError("SOLD_OUT", "Section PARKETT is sold out");
    expect(error).toBeInstanceOf(Error);
    expect(error.code).toBe("SOLD_OUT");
    expect(error.message).toBe("Section PARKETT is sold out");
  });
});

function setup(): BoxOffice | undefined {
  try {
    return createBoxOffice({
      sections: [
        { id: "PARKETT", capacity: 10, priceCents: 4990 },
        { id: "BALKON", capacity: 5, priceCents: 3000 },
      ],
      holdMinutes: 15,
      maxTicketsPerCustomer: 6,
      now: () => 1_000_000,
    });
  } catch {
    return undefined;
  }
}

describe("box office", () => {
  test("available returns the full capacity of a fresh section", () => {
    expect(setup()?.available("PARKETT")).toBe(10);
  });
});
EOF
